	&& \hspace{-0.45in} \mathcal{L}(\mathbf{y}, \mathbf{e}) = \sum_l\sum_h F_l^h y_l^h + \sum_g e_g (1 - \sum_l\sum_h w_{l,h}^g y_l^h) 
	\label{eq:LagFun} \\
