\begin{eqnarray}\label{eq:FirstLevel}
   \max_{0 \leq y_l^h \leq 1} \mathcal{L}_l^h(y_l^h, \mathbf{e})=F_l^hy_l^h - \sum_g w_{l,h}^g y_l^h e_g.
\end{eqnarray}

\begin{eqnarray}\label{eq:SecondLevel}
  \min_{\mathbf{e} \ge 0} \;\; q(\mathbf{e}) = \sum_l\sum_h \mathcal{L}_l^h \left( \left( y_l^h \right)^{\ast}, \mathbf{e} \right) + \sum_g e_g,
\end{eqnarray}

Since the solution to (\ref{eq:FirstLevel}) is unique, the relaxed dual problem (\ref{eq:SecondLevel}) can be solved using the following {\em subgradient method} that iteratively updates the Lagrange Multipliers~\cite{Bertsekas99}:
\begin{eqnarray}\label{eq:SubGrad}
  e_g(\tau+1) = \left[ e_g(\tau)-\alpha(\tau)(1 - \sum_l\sum_h w_{l,h}^g y_l^h) \right]^+,
\end{eqnarray}
where $\tau$ is the iteration index, $\alpha(\tau)$ is a sufficiently small positive step size and $[x]^+$ denotes $\max\{x, 0\}$.

\begin{eqnarray}\label{eq:SubGrad}
  e_g(\tau+1) = \left[ e_g(\tau)-\alpha(\tau)(1 - \sum_l\sum_h w_{l,h}^g y_l^h) \right]^+,
\end{eqnarray}

